-- Phase 4.4: persistent incidents, campaigns, evidence and reversible analyst actions.
CREATE TABLE IF NOT EXISTS security_incidents (id INTEGER PRIMARY KEY, incident_key VARCHAR(80) NOT NULL UNIQUE, title VARCHAR(255) NOT NULL, description TEXT DEFAULT '', severity VARCHAR(30) DEFAULT 'UNKNOWN', status VARCHAR(30) DEFAULT 'NEW', first_seen TIMESTAMP, last_seen TIMESTAMP, created_at TIMESTAMP, updated_at TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_security_incidents_status ON security_incidents(status);
CREATE TABLE IF NOT EXISTS security_incident_sources (id INTEGER PRIMARY KEY, incident_id INTEGER NOT NULL, source_type VARCHAR(40) NOT NULL, source_id VARCHAR(160) NOT NULL, FOREIGN KEY(incident_id) REFERENCES security_incidents(id), CONSTRAINT uq_security_incident_source UNIQUE(source_type, source_id));
CREATE INDEX IF NOT EXISTS ix_security_incident_sources_incident_id ON security_incident_sources(incident_id);
CREATE TABLE IF NOT EXISTS incident_indicators (id INTEGER PRIMARY KEY, incident_id INTEGER NOT NULL, indicator_id INTEGER NOT NULL, evidence_json TEXT DEFAULT '{}', FOREIGN KEY(incident_id) REFERENCES security_incidents(id), FOREIGN KEY(indicator_id) REFERENCES threat_indicators(id), CONSTRAINT uq_incident_indicator UNIQUE(incident_id, indicator_id));
CREATE INDEX IF NOT EXISTS ix_incident_indicators_incident_id ON incident_indicators(incident_id);
CREATE TABLE IF NOT EXISTS incident_evidence (id INTEGER PRIMARY KEY, incident_id INTEGER NOT NULL, evidence_type VARCHAR(80) NOT NULL, source VARCHAR(120) NOT NULL, confidence FLOAT, details_json TEXT DEFAULT '{}', observed_at TIMESTAMP, FOREIGN KEY(incident_id) REFERENCES security_incidents(id));
CREATE INDEX IF NOT EXISTS ix_incident_evidence_incident_id ON incident_evidence(incident_id);
CREATE TABLE IF NOT EXISTS threat_campaigns (id INTEGER PRIMARY KEY, campaign_key VARCHAR(160) NOT NULL UNIQUE, name VARCHAR(255) NOT NULL, description TEXT DEFAULT '', severity VARCHAR(30) DEFAULT 'UNKNOWN', confidence FLOAT DEFAULT 0, status VARCHAR(30) DEFAULT 'NEW', first_seen TIMESTAMP, last_seen TIMESTAMP, created_at TIMESTAMP, updated_at TIMESTAMP);
CREATE INDEX IF NOT EXISTS ix_threat_campaigns_status ON threat_campaigns(status);
CREATE TABLE IF NOT EXISTS campaign_incidents (id INTEGER PRIMARY KEY, campaign_id INTEGER NOT NULL, incident_id INTEGER NOT NULL, confidence FLOAT, explanation TEXT, association_status VARCHAR(30) DEFAULT 'ACTIVE', added_at TIMESTAMP, FOREIGN KEY(campaign_id) REFERENCES threat_campaigns(id), FOREIGN KEY(incident_id) REFERENCES security_incidents(id), CONSTRAINT uq_campaign_incident UNIQUE(campaign_id, incident_id));
CREATE INDEX IF NOT EXISTS ix_campaign_incidents_campaign_id ON campaign_incidents(campaign_id);
CREATE TABLE IF NOT EXISTS campaign_indicators (id INTEGER PRIMARY KEY, campaign_id INTEGER NOT NULL, indicator_id INTEGER NOT NULL, evidence_json TEXT DEFAULT '{}', FOREIGN KEY(campaign_id) REFERENCES threat_campaigns(id), FOREIGN KEY(indicator_id) REFERENCES threat_indicators(id), CONSTRAINT uq_campaign_indicator UNIQUE(campaign_id, indicator_id));
CREATE INDEX IF NOT EXISTS ix_campaign_indicators_campaign_id ON campaign_indicators(campaign_id);
CREATE TABLE IF NOT EXISTS campaign_evidence (id INTEGER PRIMARY KEY, campaign_id INTEGER NOT NULL, evidence_type VARCHAR(80) NOT NULL, source VARCHAR(120) NOT NULL, confidence FLOAT, details_json TEXT DEFAULT '{}', observed_at TIMESTAMP, FOREIGN KEY(campaign_id) REFERENCES threat_campaigns(id));
CREATE INDEX IF NOT EXISTS ix_campaign_evidence_campaign_id ON campaign_evidence(campaign_id);
CREATE TABLE IF NOT EXISTS campaign_audit_events (id INTEGER PRIMARY KEY, campaign_id INTEGER NOT NULL, actor VARCHAR(160) NOT NULL, action VARCHAR(80) NOT NULL, previous_status VARCHAR(30), new_status VARCHAR(30), details_json TEXT DEFAULT '{}', created_at TIMESTAMP, FOREIGN KEY(campaign_id) REFERENCES threat_campaigns(id));
CREATE INDEX IF NOT EXISTS ix_campaign_audit_events_campaign_id ON campaign_audit_events(campaign_id);
